/* Shared Academy navigation and account chrome. */
(() => {
'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={Home:'M3 10 12 3l9 7v10H3Z M9 20v-7h6v7',Compass:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M16 8l-2 6-6 2 2-6Z',Book:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3Z M12 6v15',Code:'m8 7-5 5 5 5 m8-10 5 5-5 5 m-3-13-2 20',Chart:'M4 3v17h17 M8 16v-5 M13 16V7 M18 16V4',Spark:'m12 3 2.7 6.3L21 12l-6.3 2.7L12 21l-2.7-6.3L3 12l6.3-2.7Z',Workflow:'M5 3h5v5H5Z M14 16h5v5h-5Z M7.5 8v10.5H14 M10 5.5h7v10',Briefcase:'M8 6V3h8v3 M3 6h18v14H3Z M3 11l9 3 9-3',Pen:'m4 16 12-12 4 4L8 20H4Z M13 7l4 4',People:'M9 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M2 21v-2a6 6 0 0 1 12 0v2 M17 5a4 4 0 0 1 0 7 M18 15a5 5 0 0 1 4 5',Cube:'m12 3 9 5v9l-9 5-9-5V8Z M3 8l9 5 9-5 M12 13v9',Shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z m-4 9 3 3 5-6',Arrow:'M4 12h15 m-5-5 5 5-5 5',Back:'M20 12H5 m5-5-5 5 5 5',Check:'m5 12 4 4L19 6',Search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 m5 12 6 6',Calendar:'M4 5h16v16H4Z M4 10h16 M8 3v5 M16 3v5',Award:'M12 3a6 6 0 1 0 0 12 6 6 0 0 0 0-12 M8 14l-2 7 6-3 6 3-2-7',Folder:'M3 5h7l2 3h9v12H3Z',Settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',Menu:'M4 6h16 M4 12h16 M4 18h16',Lock:'M6 10h12v11H6Z M8 10V6a4 4 0 0 1 8 0v4',Clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',Terminal:'m4 6 6 6-6 6 M13 18h7',Download:'M12 3v12 m-5-5 5 5 5-5 M4 17v4h16v-4',Help:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5 M12 17v.1',Cart:'M3 4h2l3 12h10l3-9H6 M9 21v-1 M18 21v-1'};
function icon(name,size=18){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.Book}"/></svg>`}

const nav=[
 ['home','My courses','Home','Your Academy'],['paths','Browse courses','Compass'],['studio','Practice workspace','Code'],['teaching','My teacher','People'],['portfolio','My work & assessment','Folder'],['certificates','Certificates','Award'],
 ['tools','Tools & services','Terminal','Resources'],['plan','My learning plan','Compass'],['calendar','Session calendar','Calendar'],['activity','My activity','Clock'],['guide','Academy guide','Help'],['glossary','Glossary','Book'],['shop','Orders & access','Cart']
];
const accountURL=mode=>location.protocol==='file:'?'auth.html?mode='+mode:'/'+mode;
function navigation(active,{prefix='',count=0,role=''}={}){if(active==='professional')active='studio';return nav.map(([id,title,ic,group])=>`${group?`<div class="nav-label">${group}</div>`:''}<a class="nav-link ${active===id?'active':''}" href="${id==='professional'?(prefix.startsWith('/')?'/workspace.html':'workspace.html'):prefix+'#'+id}" ${active===id?'aria-current="page"':''}>${icon(ic)}<span>${title}</span>${id==='portfolio'&&count?`<span class="nav-count">${count}</span>`:''}</a>`).join('')+(['Owner','Mentor'].includes(role)?`<div class="nav-label">Teaching & team</div><a class="nav-link ${active==='teaching-staff'?'active':''}" href="${prefix}#teaching-staff">${icon('People')}Teacher workspace</a>`:'')+(role==='Owner'?`<a class="nav-link ${active==='operations'?'active':''}" href="${prefix}#operations">${icon('Settings')}Launch & team</a>`:'')+(['Owner','Reviewer','Verifier','Mentor'].includes(role)?`<div class="nav-label">Academy operations</div><a class="nav-link ${active==='staff'?'active':''}" href="${prefix}#staff">${icon('Shield')}Review workspace</a>`:'')}
function account({name='Your learning space',role='Private practice preview',signedIn=false}={}){
 const slot=document.getElementById('account-slot');if(slot)slot.innerHTML=`<div class="avatar" style="color:var(--ink)">${esc(name[0]?.toUpperCase()||'S')}</div><div><b>${esc(name)}</b><span>${esc(role)}</span></div>`;
 const actions=document.getElementById('account-actions');if(actions)actions.innerHTML=signedIn?`<a class="account-link" href="${accountURL('account')}">My account</a>`:`<a class="account-link" href="${accountURL('sign-in')}">Sign in</a><a class="btn small primary account-register" href="${accountURL('register')}">Register</a>`;
}
function bind(){const menu=document.getElementById('mobile-menu'),sidebar=document.getElementById('sidebar');if(!menu||!sidebar)return;menu.innerHTML=icon('Menu');const close=()=>{sidebar.classList.remove('open');menu.setAttribute('aria-expanded','false');document.getElementById('nav-scrim')?.remove()};menu.onclick=()=>{const open=sidebar.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));if(open){const scrim=document.createElement('button');scrim.id='nav-scrim';scrim.className='nav-scrim';scrim.setAttribute('aria-label','Close navigation');scrim.onclick=close;document.body.append(scrim);sidebar.querySelector('a')?.focus()}else close()};sidebar.addEventListener('click',e=>{if(e.target.closest('a')&&innerWidth<=900)close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&sidebar.classList.contains('open')){close();menu.focus()}})}
window.AcademyShell={icon,nav,navigation,account,accountURL,bind};
})();
